content = lib_file['content']
lines = content.splitlines()

section=None
songs=[]
albums=[]
playlists={}  # title -> list of song dicts
current_playlist=None

def parse_song_line(line):
    # line starts with '- '
    s=line[2:].strip()  # remove '- '
    if ' by ' not in s:
        return None
    title, artists_part = s.split(' by ',1)
    artists=[a.strip() for a in artists_part.split(',') if a.strip()]
    return {'title': title.strip(), 'artists': artists}

for line in lines:
    if line.startswith('# Song Library'):
        section='songs'
        continue
    if line.startswith('# Album Library'):
        section='albums'
        continue
    if line.startswith('# Playlists'):
        section='playlists'
        current_playlist=None
        continue
    if section=='songs':
        if line.startswith('- '):
            d=parse_song_line(line)
            if d:
                songs.append(d)
        else:
            continue
    elif section=='albums':
        if line.startswith('- '):
            d=parse_song_line(line)  # same format
            if d:
                albums.append(d)
        else:
            continue
    elif section=='playlists':
        if line.startswith('## '):
            current_playlist=line[3:].strip()
            playlists[current_playlist]=[]
        elif line.startswith('- '):
            d=parse_song_line(line)
            if d and current_playlist is not None:
                playlists[current_playlist].append(d)
        else:
            continue

print('song_count_raw', len(songs))
print('album_count_raw', len(albums))
print('playlist_count', len(playlists))
print('playlist_titles', list(playlists.keys())[:10])
for k,v in list(playlists.items())[:2]:
    print('playlist', k, 'songs', len(v))

# Deduplicate songs by title+sorted artists
song_key=lambda d: (d['title'], tuple(sorted(d['artists'])))
album_key=lambda d: (d['title'], tuple(sorted(d['artists'])))

unique_songs={}
for d in songs:
    unique_songs[song_key(d)]=d
unique_albums={}
for d in albums:
    unique_albums[album_key(d)]=d

print('unique_song_count', len(unique_songs))
print('unique_album_count', len(unique_albums))

# Show sample
print('first_unique_song', list(unique_songs.values())[0])
print('first_unique_album', list(unique_albums.values())[0])

