# Search helper with early stop when we find exact title+artists

def jaccard(a,b):
    a=set(a); b=set(b)
    if not a and not b:
        return 1.0
    if not a or not b:
        return 0.0
    return len(a & b)/len(a | b)


def search_song_best(target, max_pages=30):
    title = target['title']
    t_artists = target['artists']
    query = title + ' ' + ' '.join(t_artists)
    t_set = set(t_artists)
    best=None
    best_score=-1

    page_index=0
    page_limit=20
    pages_fetched=0
    while True:
        resp = apis.spotify.search_songs(query=query, page_index=page_index, page_limit=page_limit)
        pages_fetched += 1
        if not resp:
            break

        for r in resp:
            r_title=r.get('title')
            r_artists=[a.get('name') for a in r.get('artists',[])]
            r_set=set(r_artists)
            artist_overlap=jaccard(t_set, r_set)
            exact_artists = 1.0 if r_set==t_set else 0.0
            title_match = 1.0 if r_title==title else 0.0
            score = 100*title_match + 50*exact_artists + 20*artist_overlap
            if score > best_score:
                best_score=score
                best=r
        # early stop if exact title match and exact artists set match exists
        if any((r.get('title')==title and set([a.get('name') for a in r.get('artists',[])])==t_set) for r in resp):
            # we can return best among already seen pages. best_score should be >=150
            break

        page_index += 1
        if page_index >= max_pages:
            break

    return best, pages_fetched, best_score

